window.HVAC_TOOL_CONFIGS={"fan":{"key":"fan","routes":["chon-quat","fan-sizing"],"title":["Tính áp suất & chọn quạt","Pressure loss & fan sizing"],"desc":["Cộng tổn thất trên tuyến bất lợi, xác định áp suất và công suất quạt cần thiết.","Sum losses along the critical path and determine fan pressure and power requirements."],"icon":"◎","groups":[{"title":["Loại quạt & ứng dụng","Fan type & application"],"fields":[{"key":"fanType","label":["Kiểu quạt dự kiến","Proposed fan type"],"value":"unspecified","options":[{"value":"unspecified","label":["Chưa xác định","Not specified"]},{"value":"centrifugal","label":["Quạt ly tâm","Centrifugal fan"]},{"value":"axial","label":["Quạt hướng trục","Axial fan"]},{"value":"mixed","label":["Quạt dòng hỗn hợp","Mixed-flow fan"]}]},{"key":"application","label":["Ứng dụng","Application"],"value":"supply","options":[{"value":"supply","label":["Cấp gió","Supply air"]},{"value":"exhaust","label":["Hút thải","Exhaust air"]},{"value":"pressurization","label":["Tăng áp","Pressurization"]},{"value":"smoke","label":["Hút khói","Smoke extraction"]},{"value":"kitchen","label":["Hút bếp","Kitchen exhaust"]}]}]},{"title":["Điều kiện thiết kế","Design conditions"],"fields":[{"key":"flow","label":["Lưu lượng tại quạt","Fan airflow"],"unit":"m³/h","value":2400,"min":0.001,"max":1000000,"step":"any","help":null},{"key":"rho","label":["Khối lượng riêng không khí","Air density"],"unit":"kg/m³","value":1.2,"min":0.1,"max":3,"step":"any","help":null},{"key":"mu","label":["Độ nhớt động lực","Dynamic viscosity"],"unit":"µPa·s","value":18.1,"min":1,"max":100,"step":"any","help":null},{"key":"rough","label":["Độ nhám ống gió","Duct roughness"],"unit":"mm","value":0.09,"min":0,"max":10,"step":"any","help":null}]},{"title":["Quạt và dự phòng","Fan and allowance"],"fields":[{"key":"extra","label":["Tổn thất bổ sung / ảnh hưởng lắp đặt","Additional loss / system effect"],"unit":"Pa","value":50,"min":0,"max":1000000,"step":"any","help":null},{"key":"margin","label":["Dự phòng áp suất","Pressure allowance"],"unit":"%","value":10,"min":0,"max":100,"step":"any","help":null},{"key":"eff","label":["Hiệu suất tổng áp của quạt","Fan total-pressure efficiency"],"unit":"%","value":65,"min":1,"max":100,"step":"any","help":null},{"key":"motorEff","label":["Hiệu suất động cơ","Motor efficiency"],"unit":"%","value":90,"min":1,"max":100,"step":"any","help":null},{"key":"outArea","label":["Diện tích cửa ra của quạt","Fan outlet area"],"unit":"m²","value":0.15,"min":0.001,"max":100,"step":"any","help":null}]}],"notes":[["Nhập từng đoạn nối tiếp trên một tuyến bất lợi; không cộng các nhánh song song. Lưu lượng mỗi đoạn có thể khác lưu lượng tổng tại quạt.","Enter consecutive sections on one critical path; do not add parallel branches. Section flows can differ from the total fan airflow."],["Δp = f·L/Dh·ρv²/2 + ΣK·ρv²/2 + Δp thiết bị. K áp dụng theo vận tốc của chính đoạn nhập. Nhập hệ số K từ tài liệu phù hợp với hình dạng, tỷ lệ lưu lượng và tiết diện thực tế.","Δp = f·L/Dh·ρv²/2 + ΣK·ρv²/2 + equipment loss. K uses the entered section velocity; obtain coefficients for the actual fitting geometry, flow split and reference area."],["Kết quả là tổng áp cần thiết; áp suất tĩnh quạt = tổng áp − áp suất động tại cửa ra. Không phải áp suất tĩnh ngoài của AHU. Chọn quạt bằng đường đặc tính Q–P và hiệu suất tại điểm làm việc. Không tính lực nổi nhiệt hoặc tự cân bằng mạng nhánh.","The duty is fan total pressure; fan static pressure = total pressure − outlet velocity pressure. This is not AHU external static pressure. Select using the Q–P curve and efficiency at duty. Thermal buoyancy and branch-network balancing are excluded."]],"source":["ASHRAE — Duct Design","https://handbook.ashrae.org/Handbooks/F17/SI/f17_ch21/f17_ch21_si.aspx"]},"pump":{"key":"pump","routes":["chon-bom","pump-sizing"],"title":["Tính cột áp & chọn bơm","Pump head & sizing"],"desc":["Tính tổn thất đường ống, phụ kiện và thiết bị trên tuyến bất lợi của hệ nước kín hoặc cấp nước hở.","Calculate pipe, fitting and equipment losses for a closed hydronic loop or open water system."],"icon":"◉","groups":[{"title":["Loại bơm & ứng dụng","Pump type & application"],"fields":[{"key":"pumpType","label":["Kiểu bơm dự kiến","Proposed pump type"],"value":"unspecified","options":[{"value":"unspecified","label":["Chưa xác định","Not specified"]},{"value":"end","label":["Ly tâm hút đầu","End-suction centrifugal"]},{"value":"inline","label":["Ly tâm inline","Inline centrifugal"]},{"value":"split","label":["Ly tâm hai phía hút","Double-suction centrifugal"]},{"value":"multi","label":["Đa tầng cánh","Multistage"]}]},{"key":"pumpApplication","label":["Ứng dụng","Application"],"value":"chilled","options":[{"value":"chilled","label":["Tuần hoàn nước lạnh Chiller","Chilled-water circulation"]},{"value":"condenser","label":["Nước giải nhiệt","Condenser water"]},{"value":"supply","label":["Cấp nước / tăng áp","Water supply / pressure boosting"]}]}]},{"title":["Hệ thống","System"],"fields":[{"key":"system","label":["Loại hệ thống","System type"],"value":"closed","options":[{"value":"closed","label":["Chiller / tuần hoàn kín","Chiller / closed loop"]},{"value":"open","label":["Cấp nước / hệ hở","Water supply / open system"]}]},{"key":"flow","label":["Lưu lượng qua bơm","Pump flow"],"unit":"m³/h","value":10,"min":0.001,"max":1000000,"step":"any","help":null},{"key":"temp","label":["Nhiệt độ nước","Water temperature"],"unit":"°C","value":7,"min":1,"max":80,"step":"any","help":null},{"key":"rough","label":["Độ nhám ống","Pipe roughness"],"unit":"mm","value":0.045,"min":0,"max":10,"step":"any","help":null}]},{"title":["Cột áp và hiệu suất","Head and efficiency"],"fields":[{"key":"height","label":["Chênh cao từ nguồn đến điểm cấp","Elevation from source to outlet"],"unit":"m","value":15,"min":0,"max":1000,"step":"any","help":null},{"key":"terminal","label":["Áp suất dư cần tại điểm cấp","Required outlet residual pressure"],"unit":"kPa","value":100,"min":0,"max":10000,"step":"any","help":null},{"key":"extra","label":["Cột áp bổ sung","Additional head"],"unit":"mH₂O","value":0,"min":0,"max":1000000,"step":"any","help":null},{"key":"margin","label":["Dự phòng cột áp","Head allowance"],"unit":"%","value":10,"min":0,"max":100,"step":"any","help":null},{"key":"eff","label":["Hiệu suất bơm","Pump efficiency"],"unit":"%","value":65,"min":1,"max":100,"step":"any","help":null},{"key":"motorEff","label":["Hiệu suất động cơ","Motor efficiency"],"unit":"%","value":90,"min":1,"max":100,"step":"any","help":null}]}],"notes":[["Nhập tuyến bất lợi với các đoạn nối tiếp, bao gồm cả đường cấp và hồi của hệ kín. Không cộng tổn thất các nhánh song song.","Enter consecutive sections of the critical path, including supply and return in closed loops. Do not sum parallel branches."],["H = Σ(f·L/D + K)·v²/(2g) + H thiết bị. Hệ kín không cộng chiều cao tòa nhà vào cột áp tuần hoàn; áp suất nạp vẫn cần tính riêng. Hệ hở cộng chênh cao và áp suất dư. Giả thiết nguồn cấp ở áp suất khí quyển và chênh áp suất động hai đầu không đáng kể.","H = Σ(f·L/D + K)·v²/(2g) + equipment head. Closed loops exclude building height from circulation head; fill pressure must be checked separately. Open systems add elevation and residual pressure, assuming an atmospheric source and negligible endpoint velocity-head difference."],["Chỉ dùng nước sạch, không dùng kết quả này cho glycol. Công suất động cơ là gợi ý theo công suất trục; cần kiểm tra đường đặc tính, NPSH, điểm làm việc và dải vận hành thực tế.","Pure water only; not a glycol model. The motor size is a shaft-power guide; verify the pump curve, NPSH, duty point and operating range."]],"source":["Caleffi — Hydronic operating conditions","https://www.caleffi.com/en-us/blog/5-physical-operating-conditions-hydronic-systems"]},"flow":{"key":"flow","routes":["quy-doi-luu-luong","load-to-flow"],"title":["Tải lạnh → lưu lượng gió / nước","Cooling load → air / water flow"],"desc":["Quy đổi tải lạnh thành lưu lượng thiết kế và chuyển kết quả sang công cụ chọn ống.","Convert cooling load into design flow and pass the result to duct or pipe sizing."],"icon":"⇄","groups":[{"title":["Tải lạnh","Cooling load"],"fields":[{"key":"load","label":["Tải lạnh tổng","Total cooling load"],"unit":"","value":10,"min":0.001,"max":1000000,"step":"any","help":null},{"key":"unit","label":["Đơn vị công suất","Capacity unit"],"value":"kw","options":[{"value":"kw","label":["kW","kW"]},{"value":"btu","label":["BTU/h","BTU/h"]},{"value":"tr","label":["TR (tấn lạnh)","TR (refrigeration ton)"]}]},{"key":"sensible","label":["Tỷ số tải nhiệt hiện / tải lạnh tổng (SHR)","Sensible heat ratio (SHR)"],"unit":"%","value":75,"min":0,"max":100,"step":"any","help":["SHR = tải nhiệt hiện / tải tổng. Giữ giá trị theo bài tính tải hoặc thiết bị thực tế.","SHR = sensible / total load. Use the value from your load calculation or equipment data."]}]},{"title":["Lưu lượng gió cấp","Supply airflow"],"fields":[{"key":"airMode","label":["Cách nhập chênh nhiệt gió","Air temperature input"],"value":"delta","options":[{"value":"delta","label":["Nhập ΔT","Enter ΔT"]},{"value":"temperatures","label":["Nhập nhiệt độ","Enter temperatures"]}]},{"key":"roomTemp","label":["Nhiệt độ phòng","Room temperature"],"value":24,"min":0,"max":60,"unit":"°C","step":"any"},{"key":"supplyAirTemp","label":["Nhiệt độ gió cấp","Supply air temperature"],"value":14,"min":-20,"max":59,"unit":"°C","step":"any"},{"key":"airDt","label":["Chênh nhiệt phòng − gió cấp","Room − supply air temperature difference"],"unit":"K","value":10,"min":0.1,"max":50,"step":"any","help":null}]},{"title":["Lưu lượng nước lạnh","Chilled water flow"],"fields":[{"key":"waterMode","label":["Cách nhập chênh nhiệt nước","Water temperature input"],"value":"delta","options":[{"value":"delta","label":["Nhập ΔT","Enter ΔT"]},{"value":"temperatures","label":["Nhập nhiệt độ","Enter temperatures"]}]},{"key":"supplyWaterTemp","label":["Nhiệt độ nước cấp","Supply water temperature"],"value":7,"min":1,"max":79,"unit":"°C","step":"any"},{"key":"returnWaterTemp","label":["Nhiệt độ nước hồi","Return water temperature"],"value":12,"min":1,"max":80,"unit":"°C","step":"any"},{"key":"waterDt","label":["Chênh nhiệt nước hồi − nước cấp","Return − supply water temperature difference"],"unit":"K","value":5,"min":0.1,"max":50,"step":"any","help":null}]},{"title":["Chỉnh thông số chi tiết","Detailed parameters"],"advanced":true,"fields":[{"key":"rhoAir","label":["Khối lượng riêng không khí","Air density"],"unit":"kg/m³","value":1.2,"min":0.1,"max":3,"step":"any","help":null},{"key":"cpAir","label":["Nhiệt dung riêng không khí","Air specific heat"],"unit":"kJ/(kg·K)","value":1.006,"min":0.5,"max":3,"step":"any","help":null},{"key":"waterTemp","label":["Nhiệt độ nước trung bình","Mean water temperature"],"unit":"°C","value":9.5,"min":1,"max":80,"step":"any","help":null},{"key":"cpWater","label":["Nhiệt dung riêng nước","Water specific heat"],"unit":"kJ/(kg·K)","value":4.186,"min":1,"max":6,"step":"any","help":null}]}],"notes":[["Gió cấp tính từ tải làm giảm nhiệt độ: V = Q hiện/(ρ·cp·ΔT). Nước lạnh tính từ tải tổng: V = Q tổng/(ρ·cp·ΔT).","Supply airflow uses sensible load: V = Q sensible/(ρ·cp·ΔT). Chilled water flow uses total load: V = Q total/(ρ·cp·ΔT)."],["Không đồng nhất lưu lượng gió cấp với gió tươi. Cần kiểm tra khả năng khử ẩm và tải coil bằng trạng thái không khí. Nước sạch; không tự điều chỉnh theo nồng độ glycol.","Supply airflow is not outdoor ventilation airflow. Check dehumidification and coil duty with air states. Pure-water density; no automatic glycol concentration correction."],["Tải phòng dùng để ước tính gió cấp. Tải dàn lạnh còn phụ thuộc gió tươi, hòa trộn và các tải bổ sung; không tự coi tải phòng là tải coil. Chuyển sang AHU/FAHU để tính theo trạng thái không khí.","Room load estimates supply airflow. Coil duty also depends on outdoor air, mixing and additional gains; room load is not automatically coil duty. Use AHU/FAHU for an air-state calculation."]],"source":["Caleffi — Basic hydronic circuit","https://www.caleffi.com/en-us/blog/4-basic-hydronic-circuit"]},"ventilation":{"key":"ventilation","routes":["thong-gio","ventilation"],"title":["Tính thông gió & gió tươi","Ventilation & outdoor airflow"],"desc":["Tính lưu lượng theo người, diện tích, số lần trao đổi khí hoặc phối hợp người và diện tích.","Calculate airflow by people, area, air changes or a combined people-and-area method."],"icon":"↗","groups":[{"title":["Không gian và phương pháp","Space and method"],"fields":[{"key":"method","label":["Phương pháp tính","Calculation method"],"value":"combined","options":[{"value":"combined","label":["Người + diện tích / hiệu quả phân phối","People + area / distribution effectiveness"]},{"value":"ach","label":["Số lần trao đổi không khí","Air changes per hour"]},{"value":"people","label":["Theo số người","Per person"]},{"value":"area","label":["Theo diện tích","Per area"]}]},{"key":"basis","label":["Cơ sở thiết kế (suất nhập bên dưới)","Design basis (enter rates below)"],"value":"project","options":[{"value":"project","label":["Yêu cầu dự án / thông số ví dụ","Project requirements / example inputs"]},{"value":"ashrae","label":["ASHRAE 62.1 — nhập theo phiên bản áp dụng","ASHRAE 62.1 — enter rates for the applicable edition"]},{"value":"other","label":["Tiêu chuẩn khác — nhập suất được chỉ định","Other standard — enter specified rates"]}]},{"key":"area","label":["Diện tích phòng","Room floor area"],"unit":"m²","value":100,"min":0.01,"max":1000000,"step":"any","help":null},{"key":"height","label":["Chiều cao phòng","Room height"],"unit":"m","value":3,"min":0.1,"max":100,"step":"any","help":null},{"key":"people","label":["Số người thiết kế","Design occupancy"],"unit":"người / people","value":10,"min":0,"max":100000,"step":1,"help":null}]},{"title":["Suất lưu lượng thiết kế","Design airflow rates"],"fields":[{"key":"rp","label":["Gió tươi cho mỗi người (phối hợp)","Outdoor rate per person (combined)"],"unit":"L/(s·person)","value":2.5,"min":0,"max":1000,"step":"any","help":null},{"key":"ra","label":["Gió tươi theo diện tích (phối hợp)","Outdoor rate per area (combined)"],"unit":"L/(s·m²)","value":0.3,"min":0,"max":100,"step":"any","help":null},{"key":"ezConfig","label":["Cấu hình phân phối khí (Ez)","Air distribution configuration (Ez)"],"value":"custom","options":[{"value":"custom","label":["Tùy chỉnh / chưa chọn cấu hình","Custom / no configuration selected"]},{"value":"ceilingCool","label":["Cấp lạnh từ trần · Ez = 1","Cool ceiling supply · Ez = 1"]},{"value":"warmFloorReturn","label":["Cấp nóng từ trần, hồi thấp · Ez = 1","Warm ceiling supply, low return · Ez = 1"]},{"value":"warmHigh","label":["Cấp nóng từ trần, hồi cao — ΔT ≥ 8°C · Ez = 0.8","Warm ceiling supply, high return — ΔT ≥ 8°C · Ez = 0.8"]},{"value":"warmLowThrow","label":["Cấp nóng từ trần, hồi cao — tia gió yếu · Ez = 0.8","Warm ceiling supply, high return — weak jet · Ez = 0.8"]},{"value":"warmGoodThrow","label":["Cấp nóng từ trần, hồi cao — tia gió tới vùng sử dụng · Ez = 1","Warm ceiling supply, high return — adequate throw · Ez = 1"]},{"value":"floorCoolMixed","label":["Cấp lạnh thấp, hồi cao — hòa trộn · Ez = 1","Low cool supply, high return — mixed · Ez = 1"]},{"value":"floorWarmLow","label":["Cấp nóng thấp, hồi thấp · Ez = 1","Low warm supply, low return · Ez = 1"]},{"value":"floorWarmHigh","label":["Cấp nóng thấp, hồi cao · Ez = 0.7","Low warm supply, high return · Ez = 0.7"]}]},{"key":"ez","label":["Hiệu quả phân phối khí vùng","Zone air distribution effectiveness"],"unit":"","value":1,"min":0.1,"max":2,"step":"any","help":["Chọn cấu hình hoặc nhập Ez theo hồ sơ thiết kế. Chỉ dùng với phương pháp phối hợp người + diện tích.","Choose a configuration or enter the design Ez. Used only by the combined people + area method."]},{"key":"ach","label":["Số lần trao đổi không khí","Air changes per hour"],"unit":"lần/giờ · h⁻¹","value":6,"min":0,"max":200,"step":"any","help":null},{"key":"personRate","label":["Lưu lượng mỗi người (riêng)","Standalone per-person rate"],"unit":"L/(s·person)","value":10,"min":0,"max":1000,"step":"any","help":null},{"key":"areaRate","label":["Lưu lượng theo diện tích (riêng)","Standalone per-area rate"],"unit":"L/(s·m²)","value":1,"min":0,"max":100,"step":"any","help":null}]}],"notes":[["Các suất mặc định chỉ là ví dụ để thao tác, không là yêu cầu cho mọi loại phòng. Nhập suất theo công năng, tiêu chuẩn và phiên bản áp dụng cho dự án.","Default rates are entry examples, not requirements for every occupancy. Enter rates from the occupancy, standard and edition applicable to the project."],["Phối hợp: Vbz = Rp·P + Ra·A; Voz = Vbz/Ez. Phương pháp số lần trao đổi khí: V = A·h·ACH. Bốn phương pháp là lựa chọn riêng, không tự cộng hoặc lấy lớn nhất.","Combined method: Vbz = Rp·P + Ra·A; Voz = Vbz/Ez. Air-change method: V = A·h·ACH. The four methods are separate alternatives, not automatically summed or maximized."],["Kết quả phối hợp chỉ là gió ngoài cho một vùng. Chưa tính hiệu quả thông gió hệ nhiều vùng, đa dạng người, điều khiển theo nhu cầu hay điều chỉnh mật độ không khí theo phiên bản tiêu chuẩn. Không dùng để tính hút khói hoặc tăng áp cầu thang.","The combined result is single-zone outdoor air only. Multizone system efficiency, population diversity, demand control and edition-specific density adjustments are excluded. Not a smoke extraction or stair pressurization calculation."]],"source":["ASHRAE — Ventilation and Infiltration","https://handbook.ashrae.org/Handbooks/F21/IP/f21_ch16/f21_ch16_ip.aspx"]},"grille":{"key":"grille","routes":["mieng-gio","grille-sizing"],"title":["Tính chọn miệng gió","Air grille sizing"],"desc":["Ước tính diện tích hữu dụng, kích thước mặt và số lượng miệng gió theo lưu lượng.","Estimate free area, face dimensions and grille count from airflow."],"icon":"▦","groups":[{"title":["Thông số chọn","Sizing inputs"],"fields":[{"key":"kind","label":["Loại miệng gió","Diffuser / grille type"],"value":"rect","options":[{"value":"linear","label":["Linear — mặt dài","Linear — elongated face"]},{"value":"rect","label":["Miệng gió chữ nhật","Rectangular grille"]},{"value":"round","label":["Miệng gió tròn","Circular diffuser"]},{"value":"fourway","label":["Miệng gió vuông","Square diffuser"]}]},{"key":"flow","label":["Tổng lưu lượng gió","Total airflow"],"unit":"m³/h","value":2400,"min":0.001,"max":1000000,"step":"any","help":null},{"key":"count","label":["Số lượng miệng gió","Number of grilles"],"unit":"","value":4,"min":1,"max":10000,"step":1,"help":null},{"key":"velocity","label":["Vận tốc qua diện tích hữu dụng","Free-area velocity"],"unit":"m/s","value":2.5,"min":0.1,"max":20,"step":"any","help":null},{"key":"free","label":["Tỷ lệ diện tích hữu dụng / diện tích mặt","Free area / face area ratio"],"unit":"%","value":60,"min":1,"max":100,"step":"any","help":null}]},{"title":["Kiểm tra kích thước có sẵn","Check an existing face size"],"fields":[{"key":"quick","label":["Chọn nhanh kích thước mặt tham khảo","Quick reference face size"],"value":"custom","options":[{"value":"custom","label":["Tự nhập kích thước","Custom dimensions"]}],"help":["Kích thước mặt tham khảo. Kiểm tra cổ nối và diện tích hữu dụng theo catalogue.","Reference face sizes. Check neck dimensions and free area against the catalogue."]},{"key":"width","label":["Chiều rộng / chiều dài / đường kính mặt","Face width / length / diameter"],"unit":"mm","value":400,"min":1,"max":10000,"step":"any","help":null},{"key":"height","label":["Chiều cao mặt miệng gió","Grille face height"],"unit":"mm","value":300,"min":1,"max":10000,"step":"any","help":null}]}],"notes":[["Diện tích hữu dụng = lưu lượng mỗi miệng / vận tốc. Diện tích mặt = diện tích hữu dụng / tỷ lệ diện tích hữu dụng. Lưu lượng chia đều cho các miệng.","Free area = flow per grille / velocity. Face area = free area / free-area ratio. Flow is distributed equally among grilles."],["Tỷ lệ 60% là ví dụ, cần thay theo catalogue. Kích thước là mặt danh nghĩa, không phải cổ nối hay diện tích thoáng thực tế. Danh sách chọn nhanh là kích thước tham khảo, không bảo đảm có ở mọi hãng.","60% is an example; replace it with catalogue data. Dimensions are nominal face sizes, not neck sizes or actual open area. Quick sizes are references and are not available from every manufacturer."],["Đây là lựa chọn sơ bộ theo diện tích, chưa chọn được mã sản phẩm. Cần kiểm tra độ ồn, tầm thổi, độ rơi, chênh áp và khả năng phân phối khí trong catalogue.","This is preliminary area sizing, not product selection. Check noise, throw, drop, pressure loss and air distribution in the manufacturer catalogue."],["Miệng gió vuông dùng hai cạnh bằng nhau; tròn dùng πD²/4; chữ nhật và Linear dùng dài × rộng. Linear được ước tính theo diện tích mặt và tỷ lệ hữu dụng do người dùng nhập, chưa chọn số khe hoặc bề rộng khe. Tỷ lệ hữu dụng không tự thay khi đổi loại.","Square diffusers use equal sides; circular uses πD²/4; rectangular and linear use length × width. Linear sizing uses face area and the entered free-area ratio; it does not select slot count or slot width. Changing type does not change the free-area ratio."],["Tối đa 10 phương án nhỏ nhất đạt vận tốc được chọn trước khi sắp xếp cột. Vuông/tròn: bước 50 mm, 100–2.000 mm; chữ nhật: bước 50 mm và tỷ lệ cạnh ≤4. Linear: dài 300–2.000 mm, rộng 50/75/100/150/200/250/300 mm, tỷ lệ dài/rộng ≥3. Danh sách là phương án hình học để kiểm tra sơ bộ.","Up to 10 smallest qualifying options are selected before column sorting. Square/circular: 50 mm increments, 100–2,000 mm; rectangular: 50 mm increments and aspect ratio ≤4. Linear: length 300–2,000 mm, width 50/75/100/150/200/250/300 mm, length/width ≥3. Options are geometric preliminary checks."]],"source":["ASHRAE — Room Air Distribution","https://handbook.ashrae.org/Handbooks/F21/SI/F21_Ch20/F21_Ch20_si.aspx"]},"insulation":{"key":"insulation","routes":["cach-nhiet","insulation"],"title":["Cách nhiệt & chống đọng sương","Insulation & condensation check"],"desc":["Kiểm tra cách nhiệt và đọng sương cho ống nước, ống gió và ống môi chất lạnh.","Check insulation and condensation for water pipes, air ducts and refrigerant pipes."],"icon":"◌","groups":[{"title":["Điều kiện môi trường","Ambient conditions"],"fields":[{"key":"ambient","label":["Nhiệt độ môi trường","Ambient temperature"],"unit":"°C","value":30,"min":0,"max":60,"step":"any","help":null},{"key":"rh","label":["Độ ẩm tương đối môi trường","Ambient relative humidity"],"unit":"%","value":75,"min":1,"max":100,"step":"any","help":null},{"key":"margin","label":["Khoảng an toàn trên điểm sương","Margin above dew point"],"unit":"K","value":1,"min":0,"max":10,"step":"any","help":["Mức nhiệt độ bề mặt cần cao hơn điểm sương. Chênh lệch 1 K = 1°C.","Required surface-temperature margin above the dew point. A difference of 1 K equals 1°C."]}]},{"title":["Loại ống & chọn nhanh","Application & quick selection"],"fields":[{"key":"application","label":["Hệ thống","Application"],"value":"pipe","options":[{"value":"pipe","label":["Ống nước","Water pipe"]},{"value":"duct","label":["Ống gió","Air duct"]},{"value":"refrigerant","label":["Ống môi chất lạnh (ống gas)","Refrigerant pipe"]}]},{"key":"shape","label":["Tiết diện","Cross-section"],"value":"round","options":[{"value":"round","label":["Tròn","Round"]},{"value":"rect","label":["Chữ nhật","Rectangular"]}]},{"key":"material","label":["Vật liệu cách nhiệt","Insulation material"],"value":"custom","options":[{"value":"custom","label":["Tự nhập vật liệu","Custom material"]},{"value":"rubber","label":["Cao su lưu hóa · ArmaFlex ACE Plus","Elastomeric foam · ArmaFlex ACE Plus"]},{"value":"pe","label":["PE · Tubolit Tubes","PE · Tubolit Tubes"]},{"value":"glass","label":["Bông thủy tinh · Knauf Duct Wrap","Glass wool · Knauf Duct Wrap"]},{"value":"rock","label":["Bông khoáng · ROCKWOOL","Stone wool · ROCKWOOL"]}]},{"key":"thicknessQuick","label":["Chọn nhanh chiều dày","Quick thickness"],"value":"custom","options":[{"value":"custom","label":["Tự nhập","Custom"]}]},{"key":"width","label":["Chiều rộng ống gió","Duct width"],"value":500,"unit":"mm","step":1,"min":1,"max":10000},{"key":"height","label":["Chiều cao ống gió","Duct height"],"value":300,"unit":"mm","step":1,"min":1,"max":10000},{"key":"refrigerantSystem","label":["Hệ máy lạnh","AC system"],"value":"residential","options":[{"value":"residential","label":["Dân dụng","Residential"]},{"value":"commercial","label":["Thương mại","Commercial"]},{"value":"vrf","label":["VRV / VRF","VRV / VRF"]}]},{"key":"refrigerantLine","label":["Đường ống môi chất","Refrigerant line"],"value":"gas","options":[{"value":"gas","label":["Ống hơi / gas","Vapour / gas line"]},{"value":"liquid","label":["Ống lỏng","Liquid line"]}]},{"key":"copperSize","label":["Đường kính ngoài ống đồng","Copper outside diameter"],"value":"custom","options":[{"value":"custom","label":["Tự nhập","Custom"]},{"value":"6.35","label":["1/4 inch · 6.35 mm","1/4 inch · 6.35 mm"]},{"value":"9.525","label":["3/8 inch · 9.525 mm","3/8 inch · 9.525 mm"]},{"value":"12.7","label":["1/2 inch · 12.7 mm","1/2 inch · 12.7 mm"]},{"value":"15.875","label":["5/8 inch · 15.875 mm","5/8 inch · 15.875 mm"]},{"value":"19.05","label":["3/4 inch · 19.05 mm","3/4 inch · 19.05 mm"]},{"value":"22.225","label":["7/8 inch · 22.225 mm","7/8 inch · 22.225 mm"]},{"value":"28.575","label":["1 1/8 inch · 28.575 mm","1 1/8 inch · 28.575 mm"]},{"value":"34.925","label":["1 3/8 inch · 34.925 mm","1 3/8 inch · 34.925 mm"]},{"value":"41.275","label":["1 5/8 inch · 41.275 mm","1 5/8 inch · 41.275 mm"]},{"value":"53.975","label":["2 1/8 inch · 53.975 mm","2 1/8 inch · 53.975 mm"]}]},{"key":"manufacturerMin","label":["Chiều dày tối thiểu theo hãng","Manufacturer minimum thickness"],"value":0,"unit":"mm","step":"any","min":0,"max":300,"help":["0 = chưa nhập yêu cầu của hãng. Không tự suy ra theo loại hệ máy.","0 = manufacturer requirement not entered. Not inferred from system type."]}]},{"title":["Ống và cách nhiệt","Pipe and insulation"],"fields":[{"key":"pipe","label":["Nhiệt độ mặt ngoài ống dưới cách nhiệt","Pipe outer surface temperature under insulation"],"unit":"°C","value":7,"min":-30,"max":150,"step":"any","help":null},{"key":"d","label":["Đường kính ngoài của ống","Pipe outside diameter"],"unit":"mm","value":114.3,"min":1,"max":2000,"step":"any","help":null},{"key":"length","label":["Chiều dài ống","Pipe length"],"unit":"m","value":10,"min":0.01,"max":1000000,"step":"any","help":null},{"key":"k","label":["Hệ số dẫn nhiệt của vật liệu (λ)","Material thermal conductivity (λ)"],"unit":"W/(m·K)","value":0.035,"min":0.005,"max":1,"step":"any","help":["Giá trị càng nhỏ, vật liệu cách nhiệt càng tốt ở cùng điều kiện. Tra theo catalogue sản phẩm.","A lower value means better insulation under the same conditions. Use the product data sheet."]},{"key":"h","label":["Hệ số trao đổi nhiệt bề mặt tổng hợp","Combined external surface coefficient"],"unit":"W/(m²·K)","value":8,"min":0.1,"max":100,"step":"any","help":null},{"key":"thickness","label":["Chiều dày cần kiểm tra","Thickness to check"],"unit":"mm","value":19,"min":0,"max":300,"step":"any","help":null}]}],"notes":[["Mô hình truyền nhiệt ổn định xuyên tâm của một lớp cách nhiệt: R dẫn = ln(r₂/r₁)/(2πλ), R ngoài = 1/(h·2πr₂). Hệ số h nhập đã bao gồm đối lưu và bức xạ quy đổi.","Steady radial heat transfer through one insulation layer: R conduction = ln(r₂/r₁)/(2πλ), R outside = 1/(h·2πr₂). Enter an h that includes convection and equivalent radiation."],["Đạt chống đọng sương khi nhiệt độ bề mặt ≥ điểm sương + khoảng an toàn. Nếu mục tiêu ≥ nhiệt độ môi trường và ống lạnh, không có chiều dày hữu hạn đạt mục tiêu.","Condensation target: surface temperature ≥ dew point + margin. If the target is at or above ambient for a cold pipe, no finite thickness meets it."],["Giả thiết nhiệt độ mặt ống đã biết, λ và h không đổi. Không tính cầu nhiệt tại giá đỡ, van, lớp cản ẩm, nước xâm nhập hay nhiều lớp vật liệu. Giá trị mẫu cần đối chiếu vật liệu và điều kiện lắp đặt.","Known pipe surface temperature, constant conductivity and surface coefficient. Supports, valves, vapor barriers, moisture ingress and multilayer construction are excluded. Verify sample values against materials and installation conditions."],["Ống gió chữ nhật: ước tính mặt phẳng với R = t/λ + 1/h, q = P·(T môi trường − T mặt ống)/R, P = 2·(rộng + cao). Bỏ qua góc, cầu nhiệt và thay đổi diện tích ngoài; kết quả bề mặt không đại diện nhiệt độ nhỏ nhất tại góc.","Rectangular ducts: flat-face estimate with R = t/λ + 1/h, q = P·(ambient − bare surface temperature)/R, P = 2·(width + height). Corners, thermal bridges and outer-area changes are excluded; the face result is not the minimum corner temperature."]],"source":["ASHRAE — Insulation for Mechanical Systems","https://handbook.ashrae.org/Handbooks/F21/SI/F21_Ch23/F21_Ch23_si.aspx"]},"expansion":{"key":"expansion","routes":["binh-gian-no","expansion-vessel"],"title":["Tính bình giãn nở","Expansion vessel sizing"],"desc":["Ước tính bình màng cho hệ nước kín từ thể tích nước, nhiệt độ và áp suất.","Estimate a diaphragm vessel for a closed system from water volume, temperature and pressure."],"icon":"◍","groups":[{"title":["Thể tích và nhiệt độ","Volume and temperature"],"fields":[{"key":"volume","label":["Thể tích chất lỏng toàn hệ thống","Total system fluid volume"],"unit":"L","value":1000,"min":0.01,"max":1000000,"step":"any","help":null},{"key":"cold","label":["Nhiệt độ thấp nhất thiết kế","Lowest design temperature"],"unit":"°C","value":7,"min":4,"max":90,"step":"any","help":null},{"key":"hot","label":["Nhiệt độ cao nhất thiết kế","Highest design temperature"],"unit":"°C","value":35,"min":4,"max":90,"step":"any","help":null},{"key":"fluid","label":["Cách xác định giãn nở","Expansion input"],"value":"water","options":[{"value":"water","label":["Nước sạch — tự tính theo nhiệt độ","Pure water — calculated from temperatures"]},{"value":"custom","label":["Nhập tỷ lệ từ tài liệu chất lỏng","Expansion fraction from fluid data"]}]},{"key":"expansion","label":["Tỷ lệ tăng thể tích chất lỏng","Fluid volume increase"],"unit":"%","value":1,"min":0,"max":30,"step":"any","help":null}]},{"title":["Áp suất tại vị trí bình","Pressures at vessel location"],"fields":[{"key":"pre","label":["Áp suất nạp khí trước khi nạp nước","Gas pre-charge before filling"],"unit":"bar(g)","value":1,"min":0,"max":20,"step":"any","help":null},{"key":"fill","label":["Áp suất nạp nước lúc lạnh","Cold fill pressure"],"unit":"bar(g)","value":1.3,"min":0,"max":25,"step":"any","help":null},{"key":"max","label":["Áp suất vận hành lớn nhất cho phép","Maximum allowed operating pressure"],"unit":"bar(g)","value":2.5,"min":0.01,"max":30,"step":"any","help":null},{"key":"atm","label":["Áp suất khí quyển","Atmospheric pressure"],"unit":"bar(abs)","value":1.01325,"min":0.5,"max":1.2,"step":"any","help":null},{"key":"reserve","label":["Lượng nước dự trữ yêu cầu trong bình","Required initial water reserve"],"unit":"L","value":3,"min":0,"max":100000,"step":"any","help":null},{"key":"margin","label":["Dự phòng dung tích","Volume allowance"],"unit":"%","value":10,"min":0,"max":100,"step":"any","help":null}]}],"notes":[["Dùng áp suất tuyệt đối: p = p đo + p khí quyển. Với khí lý tưởng đẳng nhiệt, tỷ lệ dung tích nhận thêm = p₀·(1/p lạnh − 1/p lớn nhất). Tỷ lệ nước có sẵn lúc lạnh = 1 − p₀/p lạnh.","Use absolute pressures: p = gauge pressure + atmospheric pressure. With isothermal ideal gas, incremental acceptance = p₀·(1/p cold − 1/p max). Initial water fraction = 1 − p₀/p cold."],["Dung tích = lớn hơn giữa (lượng giãn nở / tỷ lệ nhận thêm × dự phòng) và (dự trữ / tỷ lệ nước lúc lạnh). Dung tích phải đủ nhận lượng giãn nở và giữ dự trữ ban đầu. Nhiệt độ nước sạch giới hạn 4–90°C; dùng tỷ lệ giãn nở từ nhà sản xuất cho glycol hoặc chất lỏng khác.","Volume = max(expansion / incremental acceptance × allowance, reserve / initial water fraction). The vessel must accept the expansion and hold the initial reserve. Pure-water temperatures are limited to 4–90°C; use manufacturer expansion data for glycol or other fluids."],["Áp suất nạp khí ≤ áp suất nạp nước lạnh < áp suất lớn nhất. Áp suất lớn nhất là vận hành cho phép, không nhập trực tiếp ngưỡng van an toàn khi chưa trừ khoảng dự phòng. Cần kiểm tra áp suất tĩnh tại bình, vị trí bơm, giới hạn nhiệt và áp của bình thực tế. Không dùng để chọn bình tích áp đóng/ngắt bơm.","Pre-charge ≤ cold fill < maximum pressure. Maximum is the allowed operating pressure, not the relief setpoint without its operating allowance. Verify static pressure, pump location and vessel pressure/temperature limits. Not a pump-cycling accumulator calculation."]],"source":["Caleffi — Expansion vessels","https://www.caleffi.com/sites/default/files/media/external-file/01079_EN.pdf"]},"fittings":{"key":"fittings","routes":["ton-that-phu-kien","fitting-loss"],"title":["Tổn thất phụ kiện — co, cút, tê","Fitting loss — elbows, tees & valves"],"desc":["Kiểm tra riêng một phụ kiện theo hệ số K, tiết diện tham chiếu và lưu lượng; đưa kết quả vào tuyến quạt hoặc bơm.","Check an individual fitting using its K coefficient, reference section and flow; add it to a fan or pump path."],"icon":"⤴","groups":[{"title":["Phụ kiện cần kiểm tra","Fitting to check"],"fields":[{"key":"medium","label":["Môi chất / hệ thống","Fluid / system"],"value":"air","options":[{"value":"air","label":["Ống gió — không khí","Air ducts"]},{"value":"water","label":["Ống nước — nước sạch","Water pipes"]}]},{"key":"fitting","label":["Loại phụ kiện (hình minh họa)","Fitting type (illustration)"],"value":"elbow90","options":[{"value":"elbow90","label":["Co / cút 90°","90° elbow"]},{"value":"elbow45","label":["Co / cút 45°","45° elbow"]},{"value":"tee","label":["Tê — một đường dòng đã chọn","Tee — one selected flow path"]},{"value":"transition","label":["Thu / phình","Reducer / expansion"]},{"value":"valve","label":["Van / thiết bị","Valve / device"]},{"value":"custom","label":["Phụ kiện khác","Other fitting"]}]},{"key":"quantity","label":["Số lượng phụ kiện giống nhau","Number of identical fittings"],"unit":"","value":1,"min":1,"max":1000,"step":1},{"key":"k","label":["Hệ số tổn thất K cho một phụ kiện","K loss coefficient per fitting"],"unit":"","value":0.5,"min":0,"max":1000,"step":"any"},{"key":"source","type":"text","label":["Nguồn K / mã phụ kiện / điều kiện áp dụng","K source / fitting code / applicable conditions"],"value":"","maxLength":160}]},{"title":["Tiết diện tham chiếu của hệ số K","K coefficient reference section"],"fields":[{"key":"shape","label":["Hình dạng tiết diện tham chiếu","Reference cross-section shape"],"value":"rect","options":[{"value":"rect","label":["Chữ nhật","Rectangular"]},{"value":"round","label":["Tròn","Round"]}]},{"key":"flow","label":["Lưu lượng tại tiết diện tham chiếu","Flow at the reference section"],"unit":"","value":2400,"min":0.001,"max":1000000,"step":"any"},{"key":"flowUnit","label":["Đơn vị lưu lượng","Flow unit"],"value":"m3h","options":[{"value":"m3h","label":["m³/h","m³/h"]},{"value":"ls","label":["L/s","L/s"]},{"value":"cfm","label":["CFM (chỉ dùng không khí)","CFM (air only)"]}]},{"key":"a","label":["Chiều rộng a / đường kính trong D","Width a / internal diameter D"],"unit":"mm","value":400,"min":0.1,"max":10000,"step":"any"},{"key":"b","label":["Chiều cao b (ống chữ nhật)","Height b (rectangular duct)"],"unit":"mm","value":300,"min":0.1,"max":10000,"step":"any"}]},{"title":["Tính chất môi chất","Fluid properties"],"fields":[{"key":"rho","label":["Khối lượng riêng không khí","Air density"],"unit":"kg/m³","value":1.2,"min":0.1,"max":3,"step":"any"},{"key":"temp","label":["Nhiệt độ nước sạch","Pure water temperature"],"unit":"°C","value":7,"min":1,"max":80,"step":"any"}]}],"notes":[["Δp một phụ kiện = K × ρv²/2; v = Q/A tại tiết diện mà tài liệu K dùng làm tham chiếu. Tổng tổn thất = số lượng × Δp. Không cộng ma sát ống thẳng.","Single-fitting Δp = K × ρv²/2; v = Q/A at the section used by the K source. Total loss = count × Δp. Straight-run friction is excluded."],["K = 0,5 ban đầu chỉ là ví dụ để kiểm tra công thức, không phải hệ số mặc định cho mọi co 90°. Loại phụ kiện chỉ đổi hình minh họa, không tự thay K. Nhập hệ số từ tài liệu phù hợp với hình dạng, bán kính cong, tỷ lệ tiết diện và chia lưu lượng.","The initial K = 0.5 is an equation example, not a universal 90° elbow coefficient. Fitting type changes the illustration, not K. Enter a coefficient for the actual geometry, bend radius, area ratio and flow split."],["Với tê, chỉ tính một đường dòng đã chọn, không cộng tổn thất đường thẳng và đường nhánh. Dùng lưu lượng và tiết diện tham chiếu đúng với K của đường đó. Phiên bản này nhận K không âm; không mô hình hóa tê hòa trộn có K âm.","For tees, check one selected flow path; do not add straight-through and branch losses. Use the reference flow and area specified by the coefficient source. This version accepts nonnegative K; mixing-junction negative-K cases are excluded."],["Thêm vào tuyến chuyển số lượng × K, lưu lượng và kích thước tham chiếu thành một dòng phụ kiện có chiều dài bằng 0. Tuyến sẽ tính lại theo môi chất đang dùng. Dữ liệu tuyến trong phiên làm việc được giữ để bổ sung nhiều phụ kiện; kiểm tra lại tuyến bất lợi và điều kiện tính.","Add to path transfers count × K, reference flow and dimensions as a zero-length fitting row. The path recalculates with its own fluid properties. Session drafts preserve the path for multiple additions; review the critical path and calculation conditions."],["Hình là sơ đồ nguyên lý, không theo tỷ lệ và không biểu thị kích thước chế tạo. Chế độ nước chỉ dùng nước sạch; khi đổi môi chất, lưu lượng và kích thước được nạp ví dụ phù hợp.","The illustration is schematic, not to scale or a fabrication drawing. Water mode uses pure water only. Switching fluid loads suitable sample flow and dimensions."]],"source":["ASHRAE — Duct Design: Fitting Losses","https://handbook.ashrae.org/Handbooks/F17/SI/f17_ch21/f17_ch21_si.aspx"]}};
